package com.campusconnect.attendance; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; import java.time.LocalDate; public interface AttendanceRepository extends JpaRepository<AttendanceRecord,Long>{ List<AttendanceRecord> findByStudentEmailOrderByAttendanceDateDesc(String email); List<AttendanceRecord> findByCourseIdAndAttendanceDate(Long courseId,LocalDate date); List<AttendanceRecord> findByCourseIdOrderByAttendanceDateDesc(Long courseId); Optional<AttendanceRecord> findByCourseIdAndStudentEmailAndAttendanceDate(Long courseId,String email,LocalDate date); }
